<script setup lang="ts">
import {computed,onMounted,reactive,ref} from "vue";
import {localDb} from "@taher/db";
import {supabase,useAuthStore,type AppRole} from "../stores/auth.store";
import {useToast} from "../composables/toast";
import {generateCompanyDemoData} from "../services/demo-data.service";
const auth=useAuthStore(),toast=useToast();
const companyId=computed(()=>auth.activeCompany?.id??"");
const isAdmin=computed(()=>["company_admin","super_admin"].includes(auth.activeRole??""));
const busy=ref(false),loadingMembers=ref(false),logoFile=ref<File|null>(null),logoPreview=ref(""),logoUrl=ref("");
const form=reactive({name:"",owner_name:"",currency_code:"DZD"});
const members=ref<Array<{id:string;user_id:string;role:AppRole;is_active:boolean;created_at:string}>>([]);
const newMember=reactive({user_id:"",role:"data_entry" as AppRole});
const roles:Array<{value:AppRole;label:string}>=[{value:"company_admin",label:"مدير الشركة"},{value:"manager",label:"مسير"},{value:"accountant",label:"محاسب"},{value:"data_entry",label:"مدخل بيانات"},{value:"client",label:"عميل"}];
const currencies=[{value:"DZD",label:"الدينار الجزائري (DZD)"},{value:"EUR",label:"اليورو (EUR)"},{value:"USD",label:"الدولار الأمريكي (USD)"}];
function hydrate(){const c=auth.activeCompany;if(!c)return;form.name=c.name;form.owner_name=c.owner_name;form.currency_code=c.currency_code||"DZD";void loadLogo(c.logo_path);}
async function loadLogo(path:string|null){logoUrl.value="";if(!path||!supabase)return;const {data,error}=await supabase.storage.from("company-archives").createSignedUrl(path,3600);if(!error&&data?.signedUrl)logoUrl.value=data.signedUrl;}
async function loadMembers(){if(!isAdmin.value||!companyId.value||!supabase)return;loadingMembers.value=true;try{const {data,error}=await supabase.from("company_memberships").select("id,user_id,role,is_active,created_at").eq("company_id",companyId.value).is("deleted_at",null).order("created_at",{ascending:true});if(error)throw error;members.value=(data??[]) as typeof members.value;}catch(e){toast.error(e instanceof Error?e.message:"تعذر تحميل المستخدمين.");}finally{loadingMembers.value=false;}}
async function saveCompany(){if(!isAdmin.value||!companyId.value||!supabase)return;if(form.name.trim().length<2||form.owner_name.trim().length<2){toast.error("أدخل اسم الشركة واسم المالك بشكل صحيح.");return;}busy.value=true;try{const {error}=await supabase.from("companies").update({name:form.name.trim(),owner_name:form.owner_name.trim(),currency_code:form.currency_code}).eq("id",companyId.value);if(error)throw error;const c=await localDb.companies.get(companyId.value);if(c){const t=new Date().toISOString();await localDb.companies.put({...c,name:form.name.trim(),owner_name:form.owner_name.trim(),currency_code:form.currency_code,updated_at:t,_updated_at:t,_synced:1});}await auth.refreshAccountState();hydrate();toast.success("تم حفظ بيانات الشركة.");}catch(e){toast.error(e instanceof Error?e.message:"تعذر حفظ بيانات الشركة.");}finally{busy.value=false;}}
function chooseLogo(event:Event){const f=(event.target as HTMLInputElement).files?.[0]??null;if(!f)return;if(!["image/png","image/jpeg","image/webp","image/svg+xml"].includes(f.type)||f.size>2*1024*1024){toast.error("اختر PNG أو JPG أو WEBP أو SVG بحجم لا يتجاوز 2MB.");return;}if(logoPreview.value)URL.revokeObjectURL(logoPreview.value);logoFile.value=f;logoPreview.value=URL.createObjectURL(f);}
async function uploadLogo(){if(!isAdmin.value||!companyId.value||!supabase||!logoFile.value)return;busy.value=true;try{const f=logoFile.value,ext=f.type==="image/svg+xml"?"svg":f.type==="image/webp"?"webp":f.type==="image/png"?"png":"jpg",path=companyId.value+"/branding/logo."+ext;const {error:up}=await supabase.storage.from("company-archives").upload(path,f,{upsert:true,contentType:f.type});if(up)throw up;const {error}=await supabase.from("companies").update({logo_path:path}).eq("id",companyId.value);if(error)throw error;const c=await localDb.companies.get(companyId.value);if(c){const t=new Date().toISOString();await localDb.companies.put({...c,logo_path:path,updated_at:t,_updated_at:t,_synced:1});}logoFile.value=null;logoPreview.value="";await auth.refreshAccountState();hydrate();toast.success("تم رفع شعار الشركة وحفظه.");}catch(e){toast.error(e instanceof Error?e.message:"تعذر رفع الشعار.");}finally{busy.value=false;}}
async function addMember(){if(!isAdmin.value||!companyId.value||!supabase)return;const uid=newMember.user_id.trim();if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(uid)){toast.error("أدخل UUID صحيحاً لحساب موجود مسبقاً.");return;}busy.value=true;try{const {error}=await supabase.from("company_memberships").insert({company_id:companyId.value,user_id:uid,role:newMember.role,is_active:true});if(error)throw error;newMember.user_id="";newMember.role="data_entry";await loadMembers();toast.success("تمت إضافة الحساب إلى الشركة.");}catch(e){toast.error(e instanceof Error?e.message:"تعذرت إضافة العضوية.");}finally{busy.value=false;}}
async function updateRole(m:typeof members.value[number],role:AppRole){if(!isAdmin.value||!supabase||m.user_id===auth.user?.id)return;busy.value=true;try{const {error}=await supabase.from("company_memberships").update({role}).eq("id",m.id).eq("company_id",companyId.value);if(error)throw error;m.role=role;toast.success("تم تحديث دور المستخدم.");}catch(e){toast.error(e instanceof Error?e.message:"تعذر تحديث الدور.");await loadMembers();}finally{busy.value=false;}}
async function toggleMember(m:typeof members.value[number]){if(!isAdmin.value||!supabase||m.user_id===auth.user?.id)return;busy.value=true;try{const {error}=await supabase.from("company_memberships").update({is_active:!m.is_active}).eq("id",m.id).eq("company_id",companyId.value);if(error)throw error;m.is_active=!m.is_active;toast.success(m.is_active?"تم تفعيل المستخدم.":"تم إيقاف المستخدم.");}catch(e){toast.error(e instanceof Error?e.message:"تعذر تحديث حالة المستخدم.");await loadMembers();}finally{busy.value=false;}}
async function createDemo(){if(!isAdmin.value||!companyId.value)return;if(!window.confirm("ستُضاف بيانات تجريبية إلى هذا الجهاز فقط ولن تُرسل إلى السحابة. هل تريد المتابعة؟"))return;busy.value=true;try{const r=await generateCompanyDemoData(companyId.value,auth.user?.id??null);toast.success("أُنشئت البيانات: "+r.workers+" عمال، "+r.cash+" حركات صندوق، "+r.expenses+" مصاريف، "+r.invoices+" فواتير.");window.dispatchEvent(new CustomEvent("taher:demo-data-created"));}catch(e){toast.error(e instanceof Error?e.message:"تعذر إنشاء البيانات التجريبية.");}finally{busy.value=false;}}
onMounted(()=>{hydrate();void loadMembers();});
</script>
<template>
<section class="space-y-6">
<header class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-bold uppercase tracking-[.18em] text-emerald-600">TREASURY & WORKSPACE</p><h1 class="mt-2 text-3xl font-black tracking-tight text-[#0A192F]">الإعدادات</h1><p class="mt-2 text-sm text-slate-500">إدارة هوية الشركة والعملة وصلاحيات الوصول.</p></div><span class="rounded-full bg-slate-100 px-3 py-2 text-xs font-bold text-slate-600">{{auth.activeRole}}</span></header>
<div v-if="!isAdmin" class="panel p-6 text-sm text-slate-600">هذه الصفحة متاحة لمدير الشركة فقط.</div>
<template v-else>
<section class="panel overflow-hidden"><div class="border-b border-slate-100 bg-slate-50/70 px-6 py-5"><h2 class="font-extrabold text-slate-900">هوية الشركة</h2><p class="mt-1 text-sm text-slate-500">البيانات التي تظهر في مساحة العمل والتقارير.</p></div><div class="grid gap-6 p-6 lg:grid-cols-[1fr_280px]">
<div class="grid content-start gap-4 sm:grid-cols-2"><label class="form-field">اسم الشركة<input v-model.trim="form.name" class="form-input" maxlength="160"></label><label class="form-field">اسم المالك<input v-model.trim="form.owner_name" class="form-input" maxlength="160"></label><label class="form-field sm:col-span-2">العملة الأساسية<select v-model="form.currency_code" class="form-input"><option v-for="c in currencies" :key="c.value" :value="c.value">{{c.label}}</option></select></label><div class="sm:col-span-2"><button class="primary-button" :disabled="busy" @click="saveCompany">حفظ بيانات الشركة</button></div></div>
<div class="rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-4 text-center"><div class="mx-auto flex h-28 w-28 items-center justify-center overflow-hidden rounded-2xl border bg-white text-3xl font-black text-slate-300"><img v-if="logoPreview||logoUrl" :src="logoPreview||logoUrl" alt="شعار الشركة" class="h-full w-full object-contain"><span v-else>T</span></div><p class="mt-3 text-sm font-bold text-slate-800">شعار الشركة</p><p class="mt-1 text-xs text-slate-500">PNG / JPG / WEBP / SVG · 2MB</p><label class="secondary-button mt-4 w-full cursor-pointer">اختيار صورة<input class="sr-only" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" @change="chooseLogo"></label><button v-if="logoFile" class="primary-button mt-2 w-full" :disabled="busy" @click="uploadLogo">رفع الشعار</button></div>
</div></section>
<section class="panel overflow-hidden"><div class="border-b border-slate-100 bg-slate-50/70 px-6 py-5"><h2 class="font-extrabold text-slate-900">المستخدمون والصلاحيات</h2><p class="mt-1 text-sm text-slate-500">إدارة عضويات الحسابات الموجودة في النظام.</p></div>
<div class="grid gap-3 border-b border-slate-100 p-5 lg:grid-cols-[1fr_220px_auto]"><label class="form-field">معرّف حساب المستخدم (UUID)<input v-model.trim="newMember.user_id" class="form-input" placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"></label><label class="form-field">الدور<select v-model="newMember.role" class="form-input"><option v-for="r in roles" :key="r.value" :value="r.value">{{r.label}}</option></select></label><button class="primary-button self-end" :disabled="busy" @click="addMember">إضافة حساب موجود</button><p class="text-xs leading-5 text-slate-500 lg:col-span-3">تربط هذه العملية حساباً موجوداً مسبقاً. إنشاء حساب جديد أو دعوة بريد إلكتروني يتطلبان إعداداً خادمياً إضافياً ولا يُنفّذان بمفتاح المتصفح.</p></div>
<div class="overflow-x-auto"><table class="w-full min-w-[760px] text-right text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="px-5 py-3">معرّف الحساب</th><th class="px-5 py-3">الدور</th><th class="px-5 py-3">الحالة</th><th class="px-5 py-3">إجراء</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="m in members" :key="m.id"><td class="px-5 py-4"><code class="text-xs">{{m.user_id}}</code><span v-if="m.user_id===auth.user?.id" class="mr-2 rounded-full bg-blue-50 px-2 py-1 text-[10px] font-bold text-blue-700">أنت</span></td><td class="px-5 py-4"><select class="form-input max-w-48 !py-2" :value="m.role" :disabled="busy||m.user_id===auth.user?.id" @change="updateRole(m,($event.target as HTMLSelectElement).value as AppRole)"><option v-for="r in roles" :key="r.value" :value="r.value">{{r.label}}</option></select></td><td class="px-5 py-4"><span class="status-pill" :class="m.is_active?'status-positive':'status-negative'">{{m.is_active?'نشط':'موقوف'}}</span></td><td class="px-5 py-4"><button class="secondary-button !py-2" :disabled="busy||m.user_id===auth.user?.id" @click="toggleMember(m)">{{m.is_active?'إيقاف':'تفعيل'}}</button></td></tr><tr v-if="!loadingMembers&&!members.length"><td colspan="4" class="p-8 text-center text-slate-400">لا توجد عضويات.</td></tr><tr v-if="loadingMembers"><td colspan="4" class="p-8 text-center text-slate-400">جارٍ التحميل…</td></tr></tbody></table></div></section>
<section class="panel overflow-hidden border-emerald-100"><div class="flex flex-wrap items-center justify-between gap-4 p-6"><div><h2 class="font-extrabold text-slate-900">بيانات تجريبية</h2><p class="mt-1 max-w-2xl text-sm leading-6 text-slate-500">إنشاء سجلات عرض للعمال والصندوق والمصاريف والفواتير لإظهار الأرقام والرسوم فوراً. تبقى محلية على هذا الجهاز ولا تُزامن إلى السحابة.</p></div><button class="primary-button !bg-emerald-600 hover:!bg-emerald-700" :disabled="busy" @click="createDemo">✦ توليد بيانات تجريبية</button></div></section>
</template></section>
</template>
